const raw = $input.item.json.text || '';

function limpiarYParsear(str) {
  let limpio = str.trim();
  limpio = limpio.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/, '').trim();
  try {
    return JSON.parse(limpio);
  } catch (e) {
    return null;
  }
}

const parsed = limpiarYParsear(raw);
const categoriasValidas = ['Clases', 'Exámenes', 'Entregas', 'Estudio personal', 'Trabajos en grupo', 'Personal'];

let categoria = 'Personal';
let fecha_evento = null;
let duracion_estimada_min = null;

if (parsed && typeof parsed === 'object') {
  if (categoriasValidas.includes(parsed.categoria)) categoria = parsed.categoria;
  if (typeof parsed.fecha_evento === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(parsed.fecha_evento)) {
    fecha_evento = parsed.fecha_evento;
  }
  if (typeof parsed.duracion_estimada_min === 'number') {
    duracion_estimada_min = parsed.duracion_estimada_min;
  }
}

return { categoria, fecha_evento, duracion_estimada_min };

const item = $input.item.json;
const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];

let confirmado = false;
let titulo = null, start = null, end = null, eventId = null;

const pick = (obj, keys) => {
  for (const k of keys) {
    if (obj && typeof obj[k] === 'string' && obj[k].trim()) return obj[k].trim();
  }
  return null;
};

for (const step of steps) {
  try {
    if (step?.action?.tool !== 'HTTP_Request') continue;
    let obs = step.observation;
    if (typeof obs === 'string') obs = JSON.parse(obs);
    if (Array.isArray(obs)) obs = obs[0];
    if (!(obs && obs.ok === true)) continue;

    let input = step.action.toolInput || {};
    if (typeof input === 'string') input = JSON.parse(input);

    confirmado = true;
    titulo = pick(input, ['Titulo', 'titulo', 'title']);
    start = pick(input, ['Start', 'start']);
    end = pick(input, ['End', 'end']);
    eventId = pick(obs, ['eventId', 'eventID', 'event_id', 'id', 'Id']);
    break;
  } catch (e) {
    // observación o input no parseable: se ignora y se revisa el siguiente paso
  }
}

const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];

const hora12 = (iso) => {
  const m = /T(\d{2}):(\d{2})/.exec(iso || '');
  if (!m) return null;
  let h = parseInt(m[1], 10);
  const suf = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return `${h}:${m[2]} ${suf}`;
};

const fechaLarga = (iso) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})T/.exec(iso || '');
  if (!m) return null;
  return `${parseInt(m[3], 10)} de ${MESES[parseInt(m[2], 10) - 1]}`;
};

// Si el agente creó el evento pero no generó texto, se arma la respuesta con los datos reales
let output = item.output;
if (confirmado && !String(output || '').trim()) {
  const f = fechaLarga(start), h1 = hora12(start), h2 = hora12(end);
  output = `Listo, agendé "${titulo || 'tu evento'}"`
    + (f ? ` para el ${f}` : '')
    + (h1 && h2 ? ` de ${h1} a ${h2}` : (h1 ? ` a las ${h1}` : ''))
    + '.';
}

return { json: { output, eventoConfirmado: confirmado, eventoTitulo: titulo, eventoStart: start, eventoEnd: end, eventoId: eventId } };

const item = $input.item.json;

const CATEGORIAS = ['Clases', 'Exámenes', 'Entregas', 'Estudio personal', 'Trabajos en grupo', 'Personal'];

const normalizar = (t) => String(t || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const REGLAS = [
  ['Trabajos en grupo', /\b(grupo|grupal|equipo|colaborativo|colaborativa)\b/],
  ['Estudio personal', /\b(repaso|repasos|repasar|repasando|estudio|estudios|estudiar|estudiando|ensayo|ensayos|ensayar|ensayando|memorizar|memorizando)\b/],
  ['Exámenes', /\b(examen|examenes|prueba|pruebas|quiz|parcial|parciales|evaluacion|evaluaciones|test|supletorio|supletorios|sustentacion|sustentar|sustentando|defensa|defender|defendiendo|leccion|lecciones)\b/],
  ['Entregas', /\b(entrega|entregas|entregar|entregando|tarea|tareas|deber|deberes|proyecto|proyectos|informe|informes|exposicion|exposiciones|taller|talleres|tesis|presentacion|presentaciones|presentar|presentando)\b/],
  ['Clases', /\b(clase|clases|laboratorio|laboratorios|tutoria|tutorias|curso|cursos)\b/],
];

const detectar = (texto) => {
  const t = normalizar(texto);
  if (!t) return null;
  let mejor = null;
  for (const [cat, re] of REGLAS) {
    const m = re.exec(t);
    if (m && (mejor === null || m.index < mejor.index)) {
      mejor = { cat, index: m.index };
    }
  }
  return mejor ? mejor.cat : null;
};

if (item.eventoConfirmado !== true) {
  item.categoria = 'Personal';
  item.fecha_evento = null;
  item.duracion_estimada_min = null;
  item.eventId = null;
  item.titulo = null;
} else {
  const m = /^(\d{4}-\d{2}-\d{2})T/.exec(item.eventoStart || '');
  if (m) item.fecha_evento = m[1];

  const ini = Date.parse(item.eventoStart);
  const fin = Date.parse(item.eventoEnd);
  if (!isNaN(ini) && !isNaN(fin) && fin > ini) {
    item.duracion_estimada_min = Math.round((fin - ini) / 60000);
  }

  item.eventId = item.eventoId || null;
  item.titulo = item.eventoTitulo || null;

  const delClasificador = CATEGORIAS.includes(item.categoria) ? item.categoria : 'Personal';
  item.categoria = detectar(item.eventoTitulo)
    || (delClasificador !== 'Personal' ? delClasificador : null)
    || detectar(item.output)
    || 'Personal';
}

delete item.eventoConfirmado;
delete item.eventoTitulo;
delete item.eventoStart;
delete item.eventoEnd;
delete item.eventoId;

return { json: item };
